    Files.createDirectories(outputPath.getParent());

            // TODO API_TEST_START
            java.io.File destFile = outputPath.resolve("test_image.png").toFile();
            net.coobird.thumbnailator.tasks.io.FileImageSink fileSink = new net.coobird.thumbnailator.tasks.io.FileImageSink(destFile);
            String fileFormat = fileSink.preferredOutputFormatName();

            net.coobird.thumbnailator.tasks.io.OutputStreamImageSink osSink = new net.coobird.thumbnailator.tasks.io.OutputStreamImageSink(imageBytes);
            String osFormat = osSink.preferredOutputFormatName();

            assert fileFormat != null && fileFormat.toLowerCase().equals("png") : "Expected inferred format 'png', got " + fileFormat;
            assert net.coobird.thumbnailator.ThumbnailParameter.ORIGINAL_FORMAT.equals(osFormat) : "Expected ORIGINAL_FORMAT fallback, got " + osFormat;

            System.out.println("__CHECK__ preferredOutputFormatName " + fileFormat + "," + osFormat);
            // TODO API_TEST_END
            System.out.println("__DONE__");
        } catch (Throwable exc) {
            System.err.println("__RUN_ERR__ " + exc.getClass().getSimpleName()
                    + ": " + exc.getMessage());
            exc.printStackTrace(System.err);
            System.exit(1);
        }
    }
}
